import{_ as p,a0 as d,w as o,s as r,I as n,x as i,a1 as e,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"如何在 Linux 中更改 MAC 地址 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中更改 MAC 地址 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中更改 MAC 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中更改 MAC 地址 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200313 How to Change MAC Address in Linux","title":"如何在 Linux 中更改 MAC 地址","tag":"202003","desc":""},"relativePath":"202003/20200313 How to Change MAC Address in Linux.md","filePath":"[post].md"}'),h={name:"202003/20200313 How to Change MAC Address in Linux.md"};function g(u,s,k,f,c,b){const a=d("Link");return o(),r("div",null,[s[23]||(s[23]=n("h1",{id:"如何在-linux-中更改-mac-地址",tabindex:"-1"},[i("如何在 Linux 中更改 MAC 地址 "),n("a",{class:"header-anchor",href:"#如何在-linux-中更改-mac-地址","aria-label":"Permalink to “如何在 Linux 中更改 MAC 地址”"},"​")],-1)),s[24]||(s[24]=n("p",null,"在向你展示如何在 Linux 中更改 MAC 地址之前，讓我們首先討論為什麼要更改它。",-1)),n("p",null,[s[1]||(s[1]=i("可能有幾個原因。也許你不希望在公共網絡上公開你的實際 ",-1)),e(a,{href:"https://en.wikipedia.org/wiki/MAC_address"},{default:t(()=>[...s[0]||(s[0]=[i("MAC 地址",-1)])]),_:1}),s[2]||(s[2]=i("（也稱為物理地址）？還有可能是網絡管理員可能已在路由器或防火牆中阻止了特定的 MAC 地址。",-1))]),s[25]||(s[25]=l('<p>一個實用的“好處”是某些公共網絡（例如機場 WiFi）允許在有限的時間內免費上網。如果你還想繼續使用，那麼偽造 Mac 地址可能會欺騙網絡，讓它認為是一台新設備。這也是一個有名的原因。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202003/18/120702qdjyb7hvyj7bsrj7.jpg" alt=""></p><p>我將展示更改 MAC 地址（也稱為欺騙/偽造 MAC 地址）的步驟。</p><h3 id="在-linux-中更改-mac-地址" tabindex="-1">在 Linux 中更改 MAC 地址 <a class="header-anchor" href="#在-linux-中更改-mac-地址" aria-label="Permalink to “在 Linux 中更改 MAC 地址”">​</a></h3><p>讓我們一步步來：</p><h4 id="查找你的-mac-地址和網絡接口" tabindex="-1">查找你的 MAC 地址和網絡接口 <a class="header-anchor" href="#查找你的-mac-地址和網絡接口" aria-label="Permalink to “查找你的 MAC 地址和網絡接口”">​</a></h4>',6)),n("p",null,[s[4]||(s[4]=i("讓我們找出一些",-1)),e(a,{href:"https://itsfoss.com/find-network-adapter-ubuntu-linux/"},{default:t(()=>[...s[3]||(s[3]=[i("關於 Linux 中網卡的細節",-1)])]),_:1}),s[5]||(s[5]=i("。使用此命令獲取網絡接口詳細信息：",-1))]),s[26]||(s[26]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip link show</span></span></code></pre></div><p>在輸出中，你將看到一些詳細信息以及 MAC 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1: lo: &lt;LOOPBACK,UP,LOWER_UP&gt; mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT group default qlen 1000</span></span>
<span class="line"><span>    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00</span></span>
<span class="line"><span>2: eno1: &lt;NO-CARRIER,BROADCAST,MULTICAST,UP&gt; mtu 1500 qdisc fq_codel state DOWN mode DEFAULT group default qlen 1000</span></span>
<span class="line"><span>    link/ether 94:c6:f8:a7:d7:30 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>3: enp0s31f6: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue state UP mode DORMANT group default qlen 1000</span></span>
<span class="line"><span>    link/ether 38:42:f8:8b:a7:68 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>4: docker0: &lt;NO-CARRIER,BROADCAST,MULTICAST,UP&gt; mtu 1500 qdisc noqueue state DOWN mode DEFAULT group default</span></span>
<span class="line"><span>    link/ether 42:02:07:8f:a7:38 brd ff:ff:ff:ff:ff:ff</span></span></code></pre></div><p>如你所見，在這裏，我的網絡接口稱為 <code>enp0s31f6</code>，MAC 地址為 <code>38:42:f8:8b:a7:68</code>。</p><p>你可能需要在安全的地方記錄下來，以便稍後還原到該原始 MAC 地址。</p><p>現在你可以繼續更改 MAC 地址。</p><p>注意！</p><p>如果在當前使用的網絡接口上執行此操作，那麼可能會中斷你的網絡連接。因此，請在其他網卡上嘗試使用此方法，或者準備重啓網絡。</p><h4 id="方法-1-使用-macchanger-更改-mac-地址" tabindex="-1">方法 1：使用 Macchanger 更改 MAC 地址 <a class="header-anchor" href="#方法-1-使用-macchanger-更改-mac-地址" aria-label="Permalink to “方法 1：使用 Macchanger 更改 MAC 地址”">​</a></h4><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/03/Change_MAC_Address_Linux.jpg?ssl=1" alt=""></p>`,10)),n("p",null,[e(a,{href:"https://github.com/alobbs/macchanger"},{default:t(()=>[...s[6]||(s[6]=[i("Macchanger",-1)])]),_:1}),s[7]||(s[7]=i(" 是查看、修改和操作網卡 MAC 地址的簡單程序。它幾乎在所有 GNU/Linux 操作系統中都可用，你可以使用發行版的包安裝程序進行安裝。",-1))]),s[27]||(s[27]=l('<p>在 Arch Linux 或 Manjaro 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S macchanger</span></span></code></pre></div><p>在 Fedora、CentOS 和 RHEL 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install macchanger</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint、Kali Linux 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install macchanger</span></span></code></pre></div><p><strong>重要！</strong>系統會要求你選擇是否應將 <code>macchanger</code> 設置為在每次啓動或關閉網絡設備時自動運行。每當你接到網線或重啓 WiFi 時，它都會提供一個新的 MAC 地址。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/03/configuring_mcchanger.jpg?ssl=1" alt="Not a good idea to run it automatically"></p><p>我建議不要自動運行它，除非你確實需要每次更改 MAC 地址。因此，選擇“No”（按 <code>Tab</code> 鍵），然後按回車鍵繼續。</p><p><strong>如何使用 Macchanger 更改 MAC 地址</strong></p><p>你還記得網絡接口名稱嗎？你在前面的步驟中獲得了它。</p><p>現在，要將隨機 MAC 地址分配給該網卡，請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo macchanger -r enp0s31f6</span></span></code></pre></div><p>更改 MAC 後，使用以下命令進行驗證：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip addr</span></span></code></pre></div><p>現在你將看到已經偽造 MAC。</p><p>要將 MAC 地址更改為特定值，請使用以下命令指定自定義 MAC 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>macchanger --mac=XX:XX:XX:XX:XX:XX</span></span></code></pre></div><p>其中 XX:XX:XX:XX:XX:XX 是你要更改的新 MAC。</p><p>最後，要將 MAC 地址恢復為其原始硬件值，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>macchanger -p enp0s31f6</span></span></code></pre></div><p>但是，你不必如此。重啓系統後，更改將自動丟失，並且實際的 MAC 地址將再次恢復。</p><p>你可以隨時查看手冊頁以獲取更多詳細信息。</p><h4 id="方法-2-使用-iproute2-更改-mac-地址-中級知識" tabindex="-1">方法 2：使用 iproute2 更改 Mac 地址（中級知識） <a class="header-anchor" href="#方法-2-使用-iproute2-更改-mac-地址-中級知識" aria-label="Permalink to “方法 2：使用 iproute2 更改 Mac 地址（中級知識）”">​</a></h4><p>我建議你使用 macchanger，但如果你不想使用它，那麼可以使用另一種方法在 Linux 中更改 MAC 地址。</p><p>首先，使用以下命令關閉網卡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ip link set dev enp0s31f6 down</span></span></code></pre></div><p>接下來，使用以下命令設置新的 MAC：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ip link set dev enp0s31f6 address XX:XX:XX:XX:XX:XX</span></span></code></pre></div><p>最後，使用以下命令重新打開網絡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ip link set dev enp0s31f6 up</span></span></code></pre></div><p>現在，驗證新的 MAC 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip link show enp0s31f6</span></span></code></pre></div><p>就是這些了。你已經成功地在 Linux 中修改了 MAC 地址。敬請期待 FOSS 更多有關 Linux 教程和技巧的文章。</p><hr>',35)),n("p",null,[s[9]||(s[9]=i("via: ",-1)),e(a,{href:"https://itsfoss.com/change-mac-address-linux/"},{default:t(()=>[...s[8]||(s[8]=[i("https://itsfoss.com/change-mac-address-linux/",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=i("作者：",-1)),e(a,{href:"https://itsfoss.com/author/itsfoss/"},{default:t(()=>[...s[10]||(s[10]=[i("Dimitrios Savvopoulos",-1)])]),_:1}),s[15]||(s[15]=i(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[11]||(s[11]=[i("lujun9972",-1)])]),_:1}),s[16]||(s[16]=i(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:t(()=>[...s[12]||(s[12]=[i("geekpi",-1)])]),_:1}),s[17]||(s[17]=i(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[i("LCTT",-1)])]),_:1}),s[21]||(s[21]=i(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[i("Linux中國",-1)])]),_:1}),s[22]||(s[22]=i(" 榮譽推出",-1))])])}const x=p(h,[["render",g]]);export{A as __pageData,x as default};
